    public const int MOOD_BASE = 50;

    /// <summary>Resolve lost to a friend's death, and to anyone's.</summary>
    public const int FRIEND_DEATH_RESOLVE = 10;

    public const int DEATH_RESOLVE = 3;

    public const int MOOD_MAX = 100;

    /// <summary>Below this a survivor is miserable and works at 3/4 speed.</summary>
    public const int MISERABLE = 30;

    /// <summary>While hurt (see health.ts).</summary>
    public const double HURT_MOOD = -10;

    /// <summary>While hungry (see food.ts).</summary>
    public const double HUNGRY_MOOD = -10;

    public static void addThought(SimState state, Survivor s, string kind)
    {
        var until = state.tick + THOUGHTS[Js.Idx(kind)].duration;
        var existing = s.thoughts.find((t) => t.kind == kind);
        if (Js.T(existing))
        {
            existing.until = until;
        }
        else
        {
            s.thoughts.push(new() { kind = kind, until = until });
        }
    }

    /// <summary>Drops thoughts whose time is up. Runs every tick, so `thoughts` stays short.</summary>
    public static void forgetThoughts(SimState state, Survivor s)
    {
        if (s.thoughts.some((t) => t.until <= state.tick))
        {
            s.thoughts = s.thoughts.filter((t) => t.until > state.tick);
        }
    }

    /// <summary>What moves this survivor's mood right now, as [label, effect] pairs.</summary>
    public static List<List<object>> moodFactors(SimState state, Survivor s)
    {
        List<List<object>> factors = s.thoughts.filter((t) => t.until > state.tick).map((t) => [THOUGHTS[Js.Idx(t.kind)].label, THOUGHTS[Js.Idx(t.kind)].effect]);
        if (Js.T(Health.isHurt(s.health)))
        {
            factors.push(["hurt", HURT_MOOD]);
        }
        if (s.satiety < Food.HUNGRY)
        {
            factors.push(["hungry", HUNGRY_MOOD]);
        }
        if (s.infection != null)
        {
            factors.push(["infected", Infection.INFECTED_MOOD]);
        }
        if (s.sick != null)
        {
            factors.push(["sick", Corpses.SICK_MOOD]);
        }
        if (Js.T(Water.isThirsty(s)))
        {
            factors.push(["thirsty", Water.THIRSTY_MOOD]);
        }
        if (Js.T(Policies.policyOn(state, "rationing")))
        {
            factors.push(["on rations", Policies.RATIONED_MOOD]);
        }
        if ((Js.T(state.leaderId) && (state.leaderId != s.id)) && state.survivors.some((o) => o.id == state.leaderId))
        {
            factors.push(["a good leader", Policies.LEADER_MOOD]);
        }
        foreach (var t in Js.Iter(s.traits))
        {
            if (Skills.TRAIT_INFO[Js.Idx(t)].mood != 0)
            {
                factors.push([Skills.TRAIT_INFO[Js.Idx(t)].label, Skills.TRAIT_INFO[Js.Idx(t)].mood]);
            }
        }
        factors.push([.. Wellbeing.wellbeingFactors(s)], [.. BodyMod.bodyFactors(s)]);
        return factors;
    }

    public static double mood(SimState state, Survivor s)
    {
        var total = moodFactors(state, s).reduce((sum, /*TODO pattern*/_1) => sum + effect, MOOD_BASE);
        return JsMath.max(0, JsMath.min(MOOD_MAX, total));
    }

    public static bool isMiserable(SimState state, Survivor s)
    {
        return mood(state, s) < MISERABLE;
    }

    /// <summary>Everyone left in the colony remembers a death; friends of the dead take it hardest.</summary>
    public static void mournDeath(SimState state, Survivor dead)
    {
        var friends = Relationships.forget(state, dead);
        var wasLeader = state.leaderId == dead.id;
        if (Js.T(wasLeader))
        {
            state.leaderId = null;
        }
        foreach (var s in Js.Iter(state.survivors))
        {
            addThought(state, s, friends.has(s.id) ? "lostFriend" : "sawDeath");
            Resolve.steel(s, friends.has(s.id) ? -FRIEND_DEATH_RESOLVE : -DEATH_RESOLVE);
            if (friends.has(s.id))
            {
                Skills.earnTrait(state, s, "haunted", $"lost {Js.Str(dead.name)}");
            }
            if (Js.T(wasLeader))
            {
                addThought(state, s, "lostLeader");
            }
        }
    }
